---@class GoFishCastingState
local GoFishCastingState = Class("GoFishCastingState", GoFishBaseState)

function GoFishCastingState.new(luaDialog)
    local instance = GoFishCastingState.New()
    instance.luaDialog = luaDialog
    instance.TransferTo = luaDialog.TransferTo

    for k, v in pairs(luaDialog) do
        instance[k] = v
    end

    return instance
end

function GoFishCastingState:CanTransfer(target)
    return true
end

function GoFishCastingState:OnEnter(params)
    self.isAuto = params.isAuto

    CfUtils.SetActive(self.BtnFishNet, false)
    self.topGoodsServer:HideMe()
    self.placeNameServer:HideMe()
    self.fishingGoodsServer:HideMe()
    --self.btnLeaveServer:ShowMe()
    self.leftPanelServer:IsBlockClick(true)
    self.btnFishingGroupServer:HideMe()
    self.btnFishingGroupServer:AddClickListener(nil)

    self.roleAnimServer:ChangeRoleStatus(ConstantsFishing.RoleStatus.Cast)

    self.throwPoleServer:ShowMe()
    if self.isAuto then
        cs_coroutine.yield_return(WaitForSeconds(2))
        self:OnPoleClick()
    else
        self.throwPoleServer:AddClickListener(self, self.OnPoleClick)
    end

    CfUtils.SetUISwitchImage(self.ImgFishing, 1)
    CfUtils.SetUISwitchImage(self.TextPullPole, 1)

    CfUtils.SetActive(self.CommonPrivilegeCardNode, false)

end

function GoFishCastingState:OnPoleClick()
    self.throwPoleServer:OnClick(self.isAuto, function(fishId, type)
        if fishId <= 0 then
            GameUtils.Toast(localize("没有鱼"))
            self.luaDialog:TransferTo(EGoFishState.Ready)
        else
            local params = {
                isAuto = self.isAuto,
                fishId = fishId,
                type = type
            }
            self.TransferTo(EGoFishState.Fishing, params)
        end
    end)

end

function GoFishCastingState:Update()
    self.throwPoleServer:OnUpdate()
end

function GoFishCastingState:OnExit()
    self.throwPoleServer:HideMe()
    self.throwPoleServer:AddClickListener(nil)
end


return GoFishCastingState